# ---- NTP stratum
def _ntp():
    b, els = [], {}
    rows = [(0, 60, [("atom", "атомные часы"), ("sat", "GPS"), ("radio", "радиочасы")]), (1, 180, [("server", ""), ("server", ""), ("server", "")]),
            (2, 300, [("server", ""), ("server", ""), ("server", ""), ("server", "")]), (15, 440, [("pc", ""), ("pc", ""), ("pc", ""), ("pc", ""), ("pc", "")])]
    pos = {}
    for lvl, y, items in rows:
        n = len(items)
        xs = [200 + (i + .5) * 560 / n for i in range(n)]
        pos[lvl] = [(x, y) for x in xs]
        b.append(f'<g class="hbx" data-id="lv{lvl}"><path class="hb" d="M20 {y - 30}H150V{y + 22}L140 {y + 32}H20Z"/><text class="hbt" x="85" y="{y - 2}" text-anchor="middle">Слой {lvl}</text>'
                 f'<text class="nsub" x="85" y="{y + 20}" text-anchor="middle">stratum {lvl}</text></g>')
    # линии
    k = 0
    for up, dn, st in ((0, 1, 2), (1, 2, 3), (2, 15, 4)):
        for i, (x2, y2) in enumerate(pos[dn]):
            x1, y1 = pos[up][min(len(pos[up]) - 1, int(i * len(pos[up]) / len(pos[dn])))]
            eid = f"nl{k}"; k += 1
            b.append(arrow(eid, x1, y1 + 30, x2, y2 - 30, "teal" if dn != 15 else "ice", dash=(dn == 15)))
            els[eid] = {"c": {0: "", st: "on"}}
    # равноправные
    (a1, ay), (a2, _), (a3, _) = pos[1]
    b.append(f'<g class="an" data-id="peer"><path class="peer" d="M{a1 + 30} {ay}H{a2 - 30} M{a2 + 30} {ay}H{a3 - 30}"/><text class="tml" x="{(a1 + a3) / 2}" y="{ay - 38}" text-anchor="middle">равноправные источники</text></g>')
    els["peer"] = {"o": {0: 0, 5: 1}}
    b.append('<text class="dots" x="480" y="378" text-anchor="middle">…</text>')
    for lvl, _, items in rows:
        for i, ((x, y), (ic, lab)) in enumerate(zip(pos[lvl], items)):
            nid = f"nn{lvl}_{i}"
            b.append(f'<g class="nd" data-id="{nid}">{hexnode(x, y, 28)}{svgicon(ic, x, y, 1.05)}</g>')
            if lab: b.append(f'<text class="nsub" x="{x}" y="{y + 46}" text-anchor="middle">{lab}</text>')
            st = {0: 1, 1: 2, 2: 3, 15: 4}[lvl]
            els[nid] = {"c": {0: "", st: "hot", st + 1: ""}}
    b.append(f'<g class="nd" data-id="n16">{hexnode(880, 440, 28)}{svgicon("pc", 880, 440, 1.05)}</g><text class="tml red" x="880" y="394" text-anchor="middle">слой 16</text>')
    b.append(f'<text class="nsub" x="880" y="490" text-anchor="middle">не синхронизирован</text>')
    els["n16"] = {"c": {0: "", 6: "bad"}}
    for lvl in (0, 1, 2, 15):
        st = {0: 1, 1: 2, 2: 3, 15: 4}[lvl]
        els[f"lv{lvl}"] = {"c": {0: "", st: "hot", st + 1: ""}}
    els["ncp"] = {"t": {0: "", 1: "Часовой слой 0 — точный источник времени, работает без задержек (атомные часы, GPS).",
                        2: "Часовой слой 1 подключён к слою 0 и имеет минимальную задержку.", 3: "Номер слоя зависит от числа переходов от доверенного источника времени.",
                        4: "Чем меньше номер слоя, тем ближе сервер к доверенному источнику. Всего существует 15 уровней.",
                        5: "Серверы одного уровня — равноправные источники времени: резервирование и проверка точности.",
                        6: "Часовой слой 16 — недоверенный: время на таких устройствах не синхронизировано."}}
    els["nsn"] = {"t": {0: "", **{i: f"{i:02d} / 06" for i in range(1, 7)}}}
    sc = scene("ntp", 6, els, {i: 2300 for i in range(7)})
    return (f'<div class="card dgc flow" {sc}><svg class="dg" viewBox="0 0 960 510" role="img">{"".join(b)}</svg>'
            f'<div class="fcap"><span class="fsn mono" data-id="nsn"></span><span class="fct" data-id="ncp"></span></div></div>')
NTP = _ntp()

